SElect S.SiteName AS RoomName,inv.cnt As SiteCount, sp.TopicName AS SponsorNameFROM dbo.[Site] s INNER JOIN SiteMetadata sm ON sm.SiteId = s.SiteIdINNER JOIN Topic sp ON sp.TopicId = sm.SponsorIdINNER JOIN (	SELECT ism.SiteId, COUNT(*) cnt	FROM InvestigativeSiteMetadata ism	GROUP BY SiteId) inv ON inv.SiteId = s.SiteId